package com.pathstudy.assessment.domain;
import com.pathstudy.curriculum.domain.AuditedEntity; import com.pathstudy.domain.User; import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; import java.time.LocalDateTime;
@Entity @Table(name="assessment_attempts", indexes={@Index(name="idx_assessment_attempt_user_started",columnList="user_id,started_at"),@Index(name="idx_assessment_attempt_version_status",columnList="assessment_version_id,status")}) @Getter @Setter @NoArgsConstructor public class AssessmentAttempt extends AuditedEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id",nullable=false) private User user; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="assessment_version_id",nullable=false) private AssessmentVersion assessmentVersion; @Column(nullable=false) private int attemptNumber; @Enumerated(EnumType.STRING) @Column(nullable=false,length=16) private AttemptStatus status=AttemptStatus.IN_PROGRESS; @Column(name="started_at",nullable=false) private LocalDateTime startedAt; private LocalDateTime submittedAt; private LocalDateTime abandonedAt; @Column(precision=10,scale=2) private BigDecimal totalScore; @Column(precision=10,scale=2) private BigDecimal maxScore; @Column(precision=7,scale=2) private BigDecimal percentage; @Version private Long version; }
